{n: len(P) for n, P in PACKINGS.items()}


CERTIFIED_UPGRADES: dict[int, np.ndarray] = {
    n: np.array(sqs, dtype=np.float64) for n, sqs in PACKINGS.items()
}


def apply_certified_upgrades(solutions: dict[int, np.ndarray]) -> int:
    """Apply certified packing upgrades to a solutions dictionary.

    Returns:
        Number of puzzles upgraded.
    """
    upgraded = 0
    for n, sqs in CERTIFIED_UPGRADES.items():
        solutions[n] = sqs.copy()
        upgraded += 1
    return upgraded
